-- Supabase PostgreSQL Database Schema for Loan App Safety Checker
-- Project: https://qjpuwpvupzigbvapkvjz.supabase.co

CREATE TABLE IF NOT EXISTS apps (
    package_id TEXT PRIMARY KEY,
    title TEXT NOT NULL,
    developer TEXT NOT NULL,
    developer_id TEXT,
    developer_email TEXT,
    developer_website TEXT,
    developer_address TEXT,
    category TEXT DEFAULT 'Finance',
    rating NUMERIC DEFAULT 0,
    rating_count BIGINT DEFAULT 0,
    installs_text TEXT,
    installs_approx BIGINT DEFAULT 0,
    privacy_policy_url TEXT,
    store_url TEXT NOT NULL,
    icon_url TEXT,
    summary TEXT,
    is_active BOOLEAN DEFAULT TRUE,
    store_status TEXT DEFAULT 'active',
    first_discovered_at TIMESTAMPTZ DEFAULT NOW(),
    last_scanned_at TIMESTAMPTZ DEFAULT NOW(),
    safety_reason TEXT,
    review_sample_count INT DEFAULT 30,
    latest_assessment JSONB
);

CREATE TABLE IF NOT EXISTS scan_runs (
    id BIGSERIAL PRIMARY KEY,
    scan_uuid TEXT UNIQUE NOT NULL,
    started_at TIMESTAMPTZ DEFAULT NOW(),
    completed_at TIMESTAMPTZ,
    status TEXT DEFAULT 'completed',
    trigger_type TEXT DEFAULT 'scheduled',
    queries_attempted JSONB,
    apps_discovered_count INT DEFAULT 0,
    apps_collected_count INT DEFAULT 0,
    apps_new_count INT DEFAULT 0,
    apps_refreshed_count INT DEFAULT 0,
    apps_failed_count INT DEFAULT 0,
    delisted_count INT DEFAULT 0,
    risk_shifts_count INT DEFAULT 0,
    collector_version TEXT,
    change_alerts JSONB
);

-- Enable Row Level Security
ALTER TABLE apps ENABLE ROW LEVEL SECURITY;
ALTER TABLE scan_runs ENABLE ROW LEVEL SECURITY;

-- Allow anonymous read access
CREATE POLICY "Allow anon read on apps" ON apps FOR SELECT USING (true);
CREATE POLICY "Allow anon read on scan_runs" ON scan_runs FOR SELECT USING (true);

